import { readFileSync, writeFileSync } from "node:fs";

const explanations = {
  "06fed183-8259-4d2f-9d40-969308077a81": { // Liebe Agnieszka
    21: { kw: "her", ex: `"her" هنا جزء من فعل مركب "her sein" ضمن تعبير زمني "ein halbes Jahr her sein" (مضى عليه نصف سنة)، ويصف مدة زمنية انقضت. أما "hin" يصف اتجاهاً بعيداً عن المتحدث لا انقضاء مدة، و"vorbei" (انتهى/مر) يُستخدم عادة لوصف انتهاء حدث لا مدة زمنية بهذا التعبير الثابت المحدد. المحفز النحوي: التعبير الثابت "es ist ... her, dass..." (مضى وقت منذ أن...) يحدد "her".`, gs: "تعبير ثابت لانقضاء مدة: es ist ... her" },
    22: { kw: "erkrankt", ex: `"erkranken" فعل يعني "يمرض" وفي زمن Perfekt (ist erkrankt) يصف حالة مرض مستجدة (أصبحت المعلمة مريضة). أما "gekränkt" (Partizip II من kränken: يجرح مشاعر شخص) معنى مختلف تماماً (إهانة لا مرض)، و"kränklich" صفة تصف ميلاً دائماً للمرض لا حدثاً مفاجئاً. المحفز النحوي: وصف حدث مرض مفاجئ (مستجد) يستدعي الفعل "erkranken" في صيغة Perfekt.`, gs: "فعل ثابت في Perfekt: ist erkrankt" },
    23: { kw: "wenn", ex: `"wenn" أداة ربط زمنية تصف حدثاً مستقبلياً (ستعود عندما يكون الامتحان قد انتهى بالفعل)، مناسبة هنا للتنبؤ بزمن مستقبلي. أما "als" تُستخدم لحدث ماضٍ فريد لا مستقبلي، و"da" (بما أن) سببية لا زمنية. المحفز النحوي: وصف زمن عودة مستقبلي متوقع يستدعي "wenn".`, gs: "أداة زمنية مستقبلية: wenn" },
    24: { kw: "zwar... aber", ex: `"zwar...aber" أداة ربط تنازلية مزدوجة (صحيح أن...لكن) تصف تناقضاً معتدلاً (المعلمة البديلة لطيفة فعلاً، لكنها بلا خبرة). أما "nicht nur...sondern" (ليس فقط...بل) تفيد الإضافة لا التناقض، و"teils...teils" (جزئياً...جزئياً) توزيع لا تناقض بين صفتين مرتبطتين بنفس الفاعل. المحفز النحوي: التناقض المعتدل بين صفتين (لطيفة لكن بلا خبرة) يستدعي "zwar...aber".`, gs: "أداة ربط تنازلية مزدوجة: zwar...aber" },
    25: { kw: "werde", ex: `"werde...legen" صيغة المستقبل الحقيقي (Futur I: werden+Infinitiv) تصف خطة مؤكدة بعد انتهاء الامتحان (سأضع كل الكتب جانباً). أما "wollte" (أردت، ماضٍ) لا يناسب خطة مستقبلية، و"würde" (Konjunktiv II) يفيد افتراضاً غير مؤكد لا خطة واثقة. المحفز النحوي: وصف خطة مستقبلية مؤكدة بعد الامتحان يستدعي "werde" (Futur I).`, gs: "المستقبل الحقيقي لخطة مؤكدة: werde...legen" },
    26: { kw: "Darauf", ex: `"sich auf etwas freuen" والضمير الظرفي "darauf" (=auf das) يشير إلى الحدث المذكور سابقاً (أيام من الراحة بعد الامتحان). أما "Dafür" (=für das) يرتبط بأفعال أخرى، و"Danach" (بعد ذلك) ظرف زمني تتابعي لا ضمير إشارة لموضوع الفرح. المحفز النحوي: التعبير الثابت "sich freuen auf" يحدد "darauf".`, gs: "تعبير ثابت + ضمير ظرفي: sich freuen darauf" },
    27: { kw: "davon", ex: `"von etwas halten" تعبير ثابت (يرى رأياً في شيء)، والضمير الظرفي "davon" (=von dem) يشير للفكرة المذكورة (زيارة بادهومبورغ والتنزه). أما "darüber" و"dazu" لا يرتبطان بفعل "halten von" الذي يحدد "von" حصراً. المحفز النحوي: التعبير الثابت "was hältst du von etwas" يحدد الضمير الظرفي "davon".`, gs: "تعبير ثابت + ضمير ظرفي: halten davon" },
    28: { kw: "dir", ex: `"jemandem auf der Nase herumtanzen" تعبير اصطلاحي ثابت (يتلاعب بشخص/لا يحترم سلطته)، والشخص المتأثر في حالة الجر (Dativ): "dir auf der Nase herumtanzen". أما "dich" حالة النصب لا تناسب هذا التعبير الذي يتطلب Dativ، و"sich" ضمير انعكاسي غائب لا يطابق المخاطَبة "du". المحفز النحوي: التعبير الاصطلاحي الثابت يحدد حالة الجر "dir".`, gs: "تعبير اصطلاحي بحالة الجر: jmdm. auf der Nase herumtanzen" },
    29: { kw: "zu beschäftigen", ex: `"es ist nicht leicht, jemanden zu beschäftigen" تركيب يتطلب صيغة "zu+Infinitiv" بعد صفة التقييم "leicht" (ليس سهلاً أن يشغل المرء طفلين طوال اليوم). أما "beschäftigen lassen" (يترك شخصاً يشغل غيره) معنى مختلف، و"beschäftigt zu sein" (أن يكون مشغولاً) يصف حالة الفاعل نفسه لا فعل إشغال الآخرين. المحفز النحوي: تركيب "es ist (nicht) leicht, zu+Infinitiv" يحدد "zu beschäftigen".`, gs: "تركيب صفة تقييم + zu-Infinitiv: es ist nicht leicht, zu..." },
    30: { kw: "wie", ex: `"einen Weg finden, wie..." تركيب ثابت (يجد طريقة كيف يتعامل مع شيء)، وأداة الاستفهام غير المباشر "wie" تصف الأسلوب/الطريقة. أما "weshalb" (لماذا/الذي بسببه) يصف السبب لا الطريقة، و"wo" (أين) أداة مكانية. المحفز النحوي: التعبير الثابت "einen Weg finden, wie" يحدد "wie".`, gs: "تعبير ثابت للطريقة: einen Weg finden, wie" },
  },
  "b09ad2e1-e81a-4c4f-8578-b29ea39666c3": { // Liebe Anna Original
    21: { kw: "vergangen", ex: `"vergangen" (Partizip II من vergehen: ينقضي/يمر) يصف مدة زمنية منقضية، بعد "seit" (منذ) التي تفتح جملة زمنية عن نقطة بداية في الماضي. أما "vergehend" صيغة اسم فاعل غير مصرّفة بهذا الشكل الشائع هنا، و"vergingen" (Präteritum) صيغة مصرّفة لا تناسب موضع الصفة الوصفية بعد "ein halbes Jahr". المحفز النحوي: وصف مدة منقضية بعد "ein halbes Jahr" يستدعي Partizip II "vergangen".`, gs: "Partizip II لوصف مدة منقضية: vergangen" },
    22: { kw: "plötzlich", ex: `"plötzlich" ظرف يعني "فجأة" ويصف حدث مرض غير متوقع (فجأة مرضت معلمتنا). أما "gleich" (حالاً/فوراً) يصف زمناً وشيكاً لا مفاجأة، و"sofort" (على الفور) أيضاً يصف سرعة تنفيذ لا مفاجأة الحدوث. المحفز النحوي: وصف حدث غير متوقع يستدعي ظرف المفاجأة "plötzlich".`, gs: "ظرف مفاجأة: plötzlich" },
    23: { kw: "wenn", ex: `"wenn" أداة ربط زمنية لحدث مستقبلي (ستعود عندما يكون الامتحان قد انتهى). أما "als" لحدث ماضٍ فريد، و"da" سببية. المحفز النحوي: زمن عودة مستقبلي متوقع يستدعي "wenn".`, gs: "أداة زمنية مستقبلية: wenn" },
    24: { kw: "zwar", ex: `"zwar...aber" (المذكورة لاحقاً في النص) أداة ربط تنازلية مزدوجة تصف تناقضاً معتدلاً (لطيفة فعلاً، لكن بلا خبرة). أما "sondern" تُستخدم بعد نفي صريح لا بعد جملة إيجابية، و"sowohl" جزء من "sowohl...als auch" الجامعة لا التنازلية. المحفز النحوي: التناقض المعتدل يستدعي الجزء الأول من "zwar...aber".`, gs: "أداة ربط تنازلية مزدوجة: zwar...aber" },
    25: { kw: "werde", ex: `"werde...legen" (Futur I) خطة مؤكدة بعد انتهاء الامتحان. أما "wollte" ماضٍ، و"würde" افتراض. المحفز النحوي: خطة مستقبلية مؤكدة تستدعي "werde".`, gs: "المستقبل الحقيقي لخطة مؤكدة: werde...legen" },
    26: { kw: "Darauf", ex: `"sich auf etwas freuen" والضمير الظرفي "darauf" يشير للحدث المذكور. أما "Damit" و"Davon" لا يرتبطان بـ"freuen auf". المحفز النحوي: التعبير الثابت "sich freuen auf" يحدد "darauf".`, gs: "تعبير ثابت + ضمير ظرفي: sich freuen darauf" },
    27: { kw: "davon", ex: `"von etwas halten" والضمير الظرفي "davon" يشير للفكرة المذكورة. أما "darüber" و"dazu" لا يرتبطان بـ"halten von". المحفز النحوي: التعبير الثابت "halten von" يحدد "davon".`, gs: "تعبير ثابت + ضمير ظرفي: halten davon" },
    28: { kw: "auf", ex: `"jemandem auf der Nase herumtanzen" تعبير اصطلاحي ثابت، وحرف الجر "auf" جزء لا يتجزأ منه (auf der Nase). أما "an" و"in" لا يشكلان هذا التعبير الاصطلاحي الثابت. المحفز النحوي: التعبير الاصطلاحي الثابت يحدد "auf".`, gs: "تعبير اصطلاحي ثابت: auf der Nase herumtanzen" },
    29: { kw: "zu beschäftigen", ex: `"es ist nicht leicht, zu+Infinitiv" تركيب يتطلب هذه الصيغة بعد صفة التقييم. أما "beschäftigen lassen" معنى مختلف، و"beschäftigt zu sein" يصف حالة الفاعل نفسه. المحفز النحوي: تركيب "es ist nicht leicht, zu..." يحدد "zu beschäftigen".`, gs: "تركيب صفة تقييم + zu-Infinitiv: es ist nicht leicht, zu..." },
    30: { kw: "zurechtkommst", ex: `"wie du mit den Kindern zurechtkommst" جملة استفهام غير مباشر (كيف تتدبرين أمرك مع الأطفال)، والفعل في زمن المضارع مصرّفاً مع "du" (zurechtkommst) لوصف قدرة حالية مستمرة. أما "zurechtkamst" (Präteritum) ماضٍ لا يناسب سياق البحث عن طريقة حالية مستمرة، و"zurechtzukommen" (مصدر مع zu) لا يصلح بعد "wie" في جملة سؤال مباشرة بهذا الشكل (يحتاج فعلاً مصرّفاً في نهاية الجملة الثانوية). المحفز النحوي: جملة "wie" الاستفهامية غير المباشرة تتطلب فعلاً مصرّفاً في النهاية يطابق الفاعل "du" في المضارع، وهو "zurechtkommst".`, gs: "فعل مصرّف في جملة استفهام غير مباشر: wie du zurechtkommst" },
  },
  "8253db62-d6e7-4550-ada0-4cd542598952": { // Liebe Anna معدل
    21: { kw: "den", ex: `جملة نسبية يعود ضمير الوصل فيها على اسم مذكر مفرد "Brief" (رسالة، مذكر)، وهو مفعول به مباشر لفعل "erhalten" (يستلم)، فيأخذ حالة النصب (Akkusativ) المذكر: "den". أما "das" حالة النصب المحايد لا تطابق جنس "Brief" المذكر، و"der" حالة الرفع لا النصب. المحفز النحوي: الفعل المتعدي "erhalten" يحكم مفعولاً به بالنصب، والاسم "Brief" مذكر، فضمير الوصل "den".`, gs: "ضمير وصل مذكر بحالة النصب: den" },
    22: { kw: "hast", ex: `"einen Urlaub verbracht haben" زمن Perfekt (habe/hast...verbracht) يصف تجربة مكتملة (قضيتِ عطلة جميلة)، مصرّف هنا مع "du" إلى "hast". أما "bist" فعل مساعد خاطئ لهذا الفعل (verbringen يُصرَّف مع haben لا sein لأنه فعل متعدٍ)، و"warst" (كنتِ، من sein) لا يناسب تركيب Perfekt مع Partizip II "verbracht". المحفز النحوي: الفعل المتعدي "verbringen" يتطلب الفعل المساعد "haben" في Perfekt، مصرّفاً مع "du" إلى "hast".`, gs: "فعل مساعد صحيح في Perfekt: hast verbracht" },
    23: { kw: "mich", ex: `"jemanden fragen" فعل متعدٍ يحكم مفعولاً به مباشراً بالنصب، وفاعل الرسالة "du" يسأل "ich" (الكاتبة)، فالضمير في حالة النصب "mich". أما "mir" حالة الجر لا يحكمها "fragen" بهذا المعنى المباشر، و"sich" ضمير انعكاسي لا يناسب (السؤال موجه من شخص لآخر لا لنفسه). المحفز النحوي: الفعل المتعدي "fragen" يحكم مفعولاً به بالنصب "mich".`, gs: "فعل متعدٍ يحكم Akkusativ: fragen mich" },
    24: { kw: "doch", ex: `"doch" أداة عطف تضادية تصف تناقضاً معتدلاً (لسنا الأصغر سناً، لكننا لسنا كباراً جداً على تعلم لغة أيضاً). أما "obwohl" أداة ربط تابعة تتطلب جملة ثانوية بترتيب مختلف، و"sondern" تُستخدم بعد نفي صريح مباشر لا بعد جملة مؤكدة كاملة. المحفز النحوي: التضاد بين جملتين رئيسيتين (فعل بترتيب عادي) يستدعي أداة العطف "doch".`, gs: "أداة عطف تضادية لجملة رئيسية: doch" },
    25: { kw: "noch", ex: `"noch jung genug" ظرف يعني "لا يزال" ويؤكد استمرار الملاءمة رغم العمر (لا نزال صغاراً بما يكفي لتعلم اللغات). أما "erst" (فقط الآن) يفيد تأخراً لا استمراراً، و"schon" (بالفعل) يفيد تحقق أبكر من المتوقع، وكلاهما لا يناسب معنى "لا يزال مناسباً رغم العمر". المحفز النحوي: التأكيد على استمرار الملاءمة رغم تقدم العمر يستدعي "noch".`, gs: "ظرف استمرارية: noch jung genug" },
    26: { kw: "bedient", ex: `"einen Computer bedienen" تعبير ثابت يعني "يُشغّل/يستخدم جهاز الحاسوب"، والفعل في Perfekt (gelernt, wie man...bedient) يصف مهارة مكتسبة. أما "bearbeitet" (يعالج بيانات/ملفاً) يصف نشاطاً على المحتوى لا تشغيل الجهاز نفسه، و"bewirkt" (يُحدث تأثيراً) معنى مختلف تماماً. المحفز النحوي: وصف تعلم استخدام جهاز الحاسوب يستدعي التعبير الثابت "einen Computer bedienen".`, gs: "تعبير ثابت: einen Computer bedienen" },
    27: { kw: "zu lernen", ex: `"Angst haben, etwas zu lernen" تركيب يتطلب "zu+Infinitiv" بعد "Angst haben" (تخاف أن تتعلم شيئاً جديداً). أما "lernen" وحدها بدون "zu" لا تكتمل بعد "Angst haben"، و"lernen müssen" (يجب أن تتعلم) يضيف إلزاماً غير مقصود هنا. المحفز النحوي: تركيب "Angst haben, zu+Infinitiv" يحدد "zu lernen".`, gs: "تركيب ثابت + zu-Infinitiv: Angst haben, zu..." },
    28: { kw: "einsetzen", ex: `"seine Kenntnisse einsetzen" تعبير ثابت يعني "يوظّف/يستخدم معرفته عملياً"، مناسب لوصف تطبيق مهارة مكتسبة في الحياة العملية (رحلات إيطاليا). أما "fortsetzen" (يواصل) معنى مختلف (استمرار لا توظيف)، و"übersetzen" (يترجم) معنى مختلف تماماً. المحفز النحوي: وصف استخدام مهارة مكتسبة عملياً يستدعي "einsetzen".`, gs: "تعبير ثابت: Kenntnisse einsetzen" },
    29: { kw: "Wenn", ex: `"wenn du mich fragst" تعبير شرطي شائع يعني "إذا سألتني/برأيي" ويقدم نصيحة مشروطة برغبة السؤال. أما "Ob" (هل/إذا، للشك) لا يناسب هذا التعبير الشرطي الشائع، و"Wann" (متى) أداة استفهام عن التوقيت. المحفز النحوي: التعبير الشرطي الشائع "wenn du mich fragst" يحدد "Wenn".`, gs: "تعبير شرطي ثابت: wenn du mich fragst" },
    30: { kw: "nämlich", ex: `"nämlich" أداة توضيحية تُقدّم تفصيلاً/سبباً لعبارة سابقة (يجب أن أتوقف، إذ لدي درس بعد قليل - توضيح لسبب التوقف). أما "also" (إذن) استنتاجية عامة، و"kaum" (بالكاد) نفي شبه تام لا معنى له هنا. المحفز النحوي: تقديم سبب/توضيح لعبارة التوقف يستدعي "nämlich".`, gs: "أداة توضيحية: nämlich" },
  },
  "21e2864d-f830-452d-8346-76e4ff32edab": { // Liebe Clara
    21: { kw: "voneinander", ex: `"voneinander hören" تعبير ثابت (يتبادلان الأخبار عن بعد). أما "miteinander" (معاً) نشاط مباشر أقوى، و"zueinander" (تجاه بعضهما) اتجاه عاطفي. المحفز النحوي: التعبير الثابت "voneinander hören" يحدد الاختيار.`, gs: "تعبير ثابت: voneinander hören" },
    22: { kw: "durch", ex: `"eine Rundreise durch Europa" تعبير ثابت (جولة عبر أوروبا). أما "über" و"von" لا يناسبان هذا التعبير. المحفز النحوي: التعبير الثابت يحدد "durch".`, gs: "تعبير ثابت: eine Rundreise durch" },
    23: { kw: "Wie", ex: `"wie du weißt" تعبير ثابت (كما تعلم). أما "als" و"wenn" لا يناسبان هذا التعبير التمهيدي. المحفز النحوي: التعبير الثابت يحدد "Wie".`, gs: "تعبير ثابت: wie du weißt" },
    24: { kw: "war", ex: `فعل الكينونة "sein" في Präteritum يصف حالة ماضية بسيطة (لم يكن متحمساً). أما "wurde" يصف تحولاً، و"würde" افتراضاً. المحفز النحوي: حالة ماضية حقيقية تستدعي "war".`, gs: "فعل الكينونة الماضي لحالة وصفية: war" },
    25: { kw: "es", ex: `تركيب غير شخصي "es ist ruhig" يصف حالة عامة، والفاعل الشكلي "es". أما "er" و"man" لا يناسبان وصف حالة عامة غير شخصية. المحفز النحوي: التركيب غير الشخصي يستدعي "es".`, gs: "فاعل شكلي لوصف حالة عامة: es" },
    26: { kw: "erste", ex: `الصفة الترتيبية "erste" بعد ضمير الملكية "meine" في حالة الرفع المؤنث تأخذ نهاية "-e". أما "ersten" و"erst" لا يطابقان هذه الحالة. المحفز النحوي: ضمير الملكية المؤنث في الرفع يفرض "-e".`, gs: "صفة ترتيبية بعد ضمير ملكية في حالة الرفع: erste" },
    27: { kw: "daran", ex: `"an etwas denken" والضمير الظرفي "daran" يشير لفكرة لاحقة. أما "darüber" و"davon" يرتبطان بأفعال أخرى. المحفز النحوي: التعبير الثابت "denken an" يحدد "daran".`, gs: "تعبير ثابت + ضمير ظرفي: denken daran" },
    28: { kw: "muss", ex: `"müssen" يصف إلزاماً حتمياً (العودة الحتمية للمكتب). أما "kann" و"mag" لا يناسبان فكرة الحتمية غير المرغوبة. المحفز النحوي: العودة الحتمية تستدعي "müssen".`, gs: "فعل إلزام حتمي: müssen" },
    29: { kw: "mir", ex: `"jemandem kommt ein Gedanke" تعبير ثابت بحالة الجر (خطرت لي فكرة). أما "ich" حالة الرفع، و"mich" حالة النصب لا تناسبان. المحفز النحوي: التعبير الثابت يحدد "mir".`, gs: "تعبير ثابت بحالة الجر: mir kommt ein Gedanke" },
    30: { kw: "könnte", ex: `"könnte" (Konjunktiv II) تصف تأملاً مستقبلياً غير مؤكد. أما "bräuchte" و"dürfte" لا يناسبان هذا التأمل الحر. المحفز النحوي: التأمل المتردد يستدعي "könnte".`, gs: "Konjunktiv II لتأمل مستقبلي متردد: könnte" },
  },
  "26839c3c-eb9d-4cce-a655-53ba287ea16d": { // Liebe Sandra Original
    21: { kw: "dich", ex: `"jemanden überraschen" فعل متعدٍ يحكم مفعولاً به بالنصب (ربما يفاجئك ذلك)، وفاعل الرسالة "du" (المخاطَبة) في حالة النصب "dich". أما "dir" حالة الجر لا يحكمها "überraschen" هذا الفعل، و"sich" ضمير غائب لا يطابق المخاطَبة. المحفز النحوي: الفعل المتعدي "überraschen" يحكم مفعولاً به بالنصب "dich".`, gs: "فعل متعدٍ يحكم Akkusativ: überraschen dich" },
    22: { kw: "könnte", ex: `"könnte" (Konjunktiv II من können) يصف احتمالاً/إمكانية متخيَّلة في الماضي (لم أكن أتصور أن عطلة بلا حياة اجتماعية ستكون مناسبة). أما "möchte" (يرغب) يفيد رغبة لا احتمالاً وصفياً، و"müsste" (يجب أن) يفيد إلزاماً لا يناسب. المحفز النحوي: التخيل الافتراضي لموقف ماضٍ يستدعي Konjunktiv II "könnte".`, gs: "Konjunktiv II لاحتمال متخيَّل: könnte" },
    23: { kw: "von", ex: `"sich von etwas erholen" فعل انعكاسي ثابت (يستريح من شيء)، وحرف الجر "von" يدل على مصدر الإرهاق (ضغط الحياة اليومية). أما "mit" و"vor" لا يشكلان هذا التعبير الثابت. المحفز النحوي: التعبير الثابت "sich erholen von" يحدد "von".`, gs: "فعل ثابت + حرف جر: sich erholen von" },
    24: { kw: "als", ex: `"als sehr angenehm empfinden" تعبير يعني "يعتبر/يشعر بشيء بصفته كذا" (أجد الطقس مريحاً جداً)، وحرف "als" يصف الصفة المُدرَكة. أما "für" (من أجل) لا يشكل هذا التعبير، و"wie" (مثل) تشبيه مجازي لا تقييماً مباشراً. المحفز النحوي: التعبير الثابت "etwas als X empfinden" يحدد "als".`, gs: "تعبير ثابت: etwas als X empfinden" },
    25: { kw: "aus", ex: `"aus zwei Inseln bestehen" تعبير ثابت (يتكون من جزيرتين)، وحرف الجر "aus" يدل على المكونات. أما "in" و"zu" لا يشكلان هذا التعبير الثابت مع "bestehen". المحفز النحوي: التعبير الثابت "bestehen aus" يحدد "aus".`, gs: "تعبير ثابت: bestehen aus" },
    26: { kw: "ist", ex: `"zu erreichen sein" تركيب حالتي (Zustandspassiv-ähnlich: sein+zu+Infinitiv) يصف إمكانية الوصول (يمكن الوصول إليها بالعبّارة)، مصرّف مع فاعل مفرد "die...Sandinsel". أما "hat" لا يشكل هذا التركيب، و"wird" يصف عملية جارية لا إمكانية ثابتة. المحفز النحوي: تركيب "sein+zu+Infinitiv" (إمكانية سلبية) يحدد "ist".`, gs: "تركيب sein+zu+Infinitiv للإمكانية: ist zu erreichen" },
    27: { kw: "lebenden", ex: `"wild lebende Tiere" (حيوانات برية) صفة مُشتقة من فعل (Partizip I: lebend) تصف الحيوانات بعد أداة تنكير غائبة (لا أداة تعريف)، وفي حالة النصب الجمع بعد "beobachten" تأخذ تصريفاً قوياً بنهاية "-en" (Akkusativ Plural بدون أداة). أما "lebende" (نهاية -e) تناسب المفرد المؤنث أو الرفع، و"lebender" (نهاية -er) لا تناسب الجمع بالنصب. المحفز النحوي: صفة جمع بدون أداة تعريف في حالة النصب تأخذ نهاية "-en".`, gs: "صفة جمع (Partizip I) بحالة النصب بدون أداة: lebenden" },
    28: { kw: "wenige", ex: `"wenige Stunden" (ساعات قليلة) صفة كمية تصف مدة قصيرة، في حالة النصب الجمع بدون أداة تعريف (مفعول به زمني: bleiben nur wenige Stunden). أما "wenigen" (نهاية -en) تناسب حالة الجر لا النصب، و"weniger" (نهاية -er، أو صيغة مقارنة "أقل") لا تناسب موضعها هنا. المحفز النحوي: حالة النصب الجمع بدون أداة تفرض نهاية "-e" على الصفة الكمية.`, gs: "صفة كمية جمع بحالة النصب بدون أداة: wenige" },
    29: { kw: "Sobald", ex: `"Sobald" أداة ربط زمنية (بمجرد أن) تصف تتابعاً فورياً (بمجرد مغادرة السياح اليوميين، يسود الهدوء). أما "Sofern" (بشرط أن) شرطية لا زمنية، و"Somit" (وبالتالي) ظرف استنتاجي مستقل لا أداة ربط تُدخل جملة ثانوية. المحفز النحوي: التتابع الفوري بين حدثين يستدعي "Sobald".`, gs: "أداة ربط زمنية فورية: Sobald" },
    30: { kw: "würdest", ex: `"gern umziehen würdest" صيغة Konjunktiv II (تودّين الانتقال) تصف رغبة مهذبة/محتملة ذُكرت سابقاً من المخاطَبة، بعد فعل "gesagt" الذي ينقل كلاماً غير مباشر بنفس صيغة الرغبة الأصلية. أما "dürftest" (يُسمح لك) يفيد إذناً لا رغبة، و"könntest" (تستطيعين) يفيد قدرة لا رغبة شخصية. المحفز النحوي: نقل رغبة سابقة معبَّر عنها بـ"gern" يستدعي صيغة الرغبة المهذبة Konjunktiv II "würdest".`, gs: "Konjunktiv II لرغبة منقولة: würdest gern umziehen" },
  },
  "0cbb3727-103b-43de-a79e-ee92097c2970": { // Liebe Sandra معدل
    21: { kw: "es", ex: `تركيب غير شخصي "es überrascht dich" (يفاجئك ذلك)، والفاعل الشكلي الإلزامي "es" الذي يشير لموضوع سيُذكر لاحقاً (bass تقضي عطلة على جزيرة). أما "was" (ماذا) أداة استفهام لا فاعل شكلي، و"das" ضمير إشارة يحتاج مرجعاً محدداً سابقاً. المحفز النحوي: التركيب "es überrascht jmdn., dass..." يحدد الفاعل الشكلي "es".`, gs: "فاعل شكلي: es überrascht" },
    22: { kw: "dass", ex: `أداة الربط "dass" تُدخل جملة تفسيرية بعد فعل "überraschen" لتوضيح موضوع المفاجأة (أنني أقضي عطلة على جزيرة). أما "ob" تفيد الشك/سؤالاً غير مباشر لا حقيقة مؤكدة، و"weil" سببية لا تفسيرية بهذا الشكل. المحفز النحوي: التركيب "es überrascht, dass..." يحدد "dass".`, gs: "أداة تفسيرية: es überrascht, dass" },
    23: { kw: "viel", ex: `"viel Stress" (ضغط كثير) صفة كمية غير معدودة (Stress اسم مجرد لا يُجمَع)، فتبقى بدون تصريف "viel" مع الأسماء المجردة المفردة. أما "viele" (جمع) تناسب أسماء معدودة جمع لا مجردة مفردة، و"großen" (كبير، مُصرَّفة) لا تناسب "Stress" بنفس التلازم اللفظي الشائع "viel Stress". المحفز النحوي: الاسم المجرد غير المعدود "Stress" يستدعي "viel" بدون تصريف.`, gs: "صفة كمية مع اسم مجرد غير معدود: viel Stress" },
    24: { kw: "was", ex: `جملة نسبية غير محددة المرجع (الطقس معتدل، وهو أمر أجده مريحاً) - "was" يعود على فكرة الجملة كاملة (الطقس المعتدل) لا اسماً محدداً بذاته. أما "das" يحتاج اسماً محدداً سابقاً يعود عليه، و"es" ضمير شخصي لا وصل. المحفز النحوي: عودة ضمير الوصل على فكرة جملة كاملة (لا اسم مفرد) يستدعي "was".`, gs: "ضمير وصل يعود على جملة كاملة: was" },
    25: { kw: "aus", ex: `"aus zwei Inseln bestehen" تعبير ثابت (يتكون من). أما "in" و"zu" لا يناسبان. المحفز النحوي: التعبير الثابت يحدد "aus".`, gs: "تعبير ثابت: bestehen aus" },
    26: { kw: "erreichen", ex: `"zu erreichen sein" تركيب (sein+zu+Infinitiv) يصف إمكانية الوصول، والفعل هنا بصيغة المصدر بعد "zu" (die...zu erreichen ist). أما "erreicht" (Partizip II) لا يناسب موضع المصدر بعد "zu" في هذا التركيب، و"erreichte" (Präteritum) مصرّفة لا مصدرية. المحفز النحوي: تركيب "zu+Infinitiv" يفرض صيغة المصدر "erreichen".`, gs: "مصدر بعد zu في تركيب الإمكانية: zu erreichen" },
    27: { kw: "lebenden", ex: `"wild lebende Tiere" صفة (Partizip I) بحالة النصب الجمع بدون أداة تأخذ نهاية "-en". أما "lebende" و"lebender" لا تناسبان هذه الحالة. المحفز النحوي: النصب الجمع بدون أداة يفرض "-en".`, gs: "صفة جمع (Partizip I) بحالة النصب بدون أداة: lebenden" },
    28: { kw: "wenige", ex: `"wenige Stunden" صفة كمية في حالة النصب الجمع بدون أداة تأخذ نهاية "-e". أما "wenigen" و"weniger" لا تناسبان. المحفز النحوي: النصب الجمع بدون أداة يفرض "-e".`, gs: "صفة كمية جمع بحالة النصب بدون أداة: wenige" },
    29: { kw: "Sobald", ex: `"Sobald" أداة ربط زمنية فورية (بمجرد أن). أما "Sofern" شرطية، و"Somit" ظرف مستقل. المحفز النحوي: التتابع الفوري يستدعي "Sobald".`, gs: "أداة ربط زمنية فورية: Sobald" },
    30: { kw: "was", ex: `"was gibt es Neues" تعبير استفهامي شائع (ما الجديد؟) يبدأ به سؤال عام عن الأخبار. أما "wie" (كيف) و"warum" (لماذا) لا يناسبان صيغة السؤال عن "أخبار جديدة" هذه تحديداً. المحفز النحوي: التعبير الاستفهامي الثابت "was gibt es Neues" يحدد "was".`, gs: "تعبير استفهامي ثابت: was gibt es Neues" },
  },
  "34f47fe6-21e2-4b82-ad85-3c9502226b84": { // Lieber Thomas
    21: { kw: "obwohl", ex: `"obwohl" أداة ربط تنازلية (رغم أن) تصف تناقضاً بين فعل التزلج والخوف السابق منه (تزلجت اليوم، رغم أنني لم أكن أثق بنفسي من قبل). أما "trotz" حرف جر يحتاج اسماً مباشراً بعده لا جملة كاملة، و"während" (أثناء/بينما) زمنية/تضادية أضعف من التنازل الصريح المقصود. المحفز النحوي: التناقض بين الفعل والثقة السابقة المفقودة يستدعي "obwohl".`, gs: "أداة ربط تنازلية لجملة ثانوية: obwohl" },
    22: { kw: "hatte", ex: `أداة الربط الزمنية الضمنية "bevor ich ankam" (قبل وصولي) تتطلب أن يكون الفعل اللاحق بزمن أسبق (Plusquamperfekt: hatte...gebucht = كانت قد حجزت) لوصف حدث سابق للوصول. أما "hat" (Perfekt) نفس زمن أو لاحق، و"hätte" (Konjunktiv II) يفيد افتراضاً غير حقيقي لا حدثاً واقعياً حدث فعلاً. المحفز النحوي: "bevor"+حدث سابق يفرضان Plusquamperfekt "hatte".`, gs: "توافق الأزمنة: bevor + Plusquamperfekt" },
    23: { kw: "wollte", ex: `"es sich anders überlegen wollen" تعبير يصف رغبة/نية (أردت أن أغير رأيي)، والفعل "wollen" في Präteritum يصف نية ماضية. أما "konnte" (استطعت) يصف قدرة لا رغبة، و"sollte" (كان ينبغي) يفيد التزاماً خارجياً لا رغبة داخلية. المحفز النحوي: التعبير عن نية شخصية داخلية (الرغبة في تغيير الرأي) يستدعي "wollte".`, gs: "فعل إرادة: wollte (نية شخصية)" },
    24: { kw: "davon", ex: `"nichts von etwas hören wollen" تعبير ثابت (لا يريد أن يسمع شيئاً عن موضوع/لا يقبل اعتراضاً)، والضمير الظرفي "davon" يشير لفكرة إعادة النظر المذكورة. أما "dafür" و"damit" لا يرتبطان بفعل "hören von" بنفس الطريقة. المحفز النحوي: التعبير الثابت "nichts hören wollen von" يحدد "davon".`, gs: "تعبير ثابت + ضمير ظرفي: nichts davon hören wollen" },
    25: { kw: "Einerseits... ...andererseits", ex: `"einerseits...andererseits" أداة ربط مزدوجة تصف جانبين متوازيين لنفس الشعور (كنت متوترة من جهة، لكن متحمسة من جهة أخرى - كلا الشعورين حقيقيان معاً وليسا متناقضين تماماً بل متزامنين). أما "weder...noch" (لا...ولا) نفي مزدوج يستبعد كليهما، و"zwar...aber" تصف تناقضاً أقوى (تصحيح انطباع) لا تعايش شعورين متزامنين بنفس القوة. المحفز النحوي: وصف شعورين متزامنين (توتر وحماس معاً) يستدعي "einerseits...andererseits".`, gs: "أداة ربط مزدوجة لجانبين متزامنين: einerseits...andererseits" },
    26: { kw: "dabei", ex: `"jemandem bei etwas helfen" + الضمير الظرفي "dabei" (=bei dem) يشير للنشاط المذكور لاحقاً (مساعدتي في شراء المعدات). أما "davon" و"dazu" لا يرتبطان بـ"helfen bei" الذي يحدد "bei" حصراً. المحفز النحوي: التعبير الثابت "helfen bei" يحدد "dabei".`, gs: "تعبير ثابت + ضمير ظرفي: helfen dabei" },
    27: { kw: "auszusuchen", ex: `"jemandem helfen, etwas auszusuchen" تركيب يتطلب "zu+Infinitiv" بعد "helfen" (ساعدتني على اختيار الأحذية...)، والفعل المركب المنفصل "aussuchen" يُدرَج "zu" بين البادئة والجذع: "auszusuchen". أما "aussuchen" بدون "zu" لا يكتمل التركيب، و"ausgesucht" (Partizip II) لا يناسب موضع المصدر. المحفز النحوي: تركيب "helfen, zu+Infinitiv" مع فعل منفصل يفرض "auszusuchen".`, gs: "zu مُدرَجة داخل فعل منفصل بعد helfen: auszusuchen" },
    28: { kw: "grundlegende", ex: `"einige grundlegende Dinge" صفة (أساسية) تصف اسماً جمعاً محايداً "Dinge" بعد أداة تنكير جمع "einige"، فتُصرَّف بنهاية "-e" (تصريف مختلط جمع في حالة النصب). أما "grundlegenden" (نهاية -en) تناسب حالة الجر لا النصب، و"grundlegender" (نهاية -er) تناسب تصريفاً قوياً بدون أداة. المحفز النحوي: "einige" (أداة تنكير جمع) قبل الصفة تفرض نهاية "-e" في حالة النصب.`, gs: "تصريف صفة جمع بعد einige: grundlegende" },
    29: { kw: "im", ex: `"im Gegensatz zu jemandem" (in+dem، مدمجة) تعبير ثابت يعني "على عكس/بخلاف شخص ما". أما "am" (an+dem) و"zum" (zu+dem) لا يشكلان هذا التعبير الثابت. المحفز النحوي: التعبير الثابت "im Gegensatz zu" يحدد "im".`, gs: "تعبير ثابت: im Gegensatz zu" },
    30: { kw: "wie", ex: `"nicht wissen, wie..." تركيب يعني "لا يعرف كيف/بأي طريقة" (لا أعرف كيف سأنجح في ذلك)، وأداة الاستفهام غير المباشر "wie" تصف الأسلوب. أما "dass" تُدخل جملة تفسيرية مؤكدة لا سؤالاً عن الطريقة، و"ob" تفيد الشك بين نعم/لا لا استفهاماً عن الكيفية. المحفز النحوي: السؤال عن "كيفية" الإنجاز يستدعي "wie".`, gs: "أداة استفهام غير مباشر عن الطريقة: wie" },
  },
  "a97557bb-e61f-42d2-b95b-285202b2a320": { // Lina
    21: { kw: "nach", ex: `"nach etwas suchen" تعبير ثابت (يبحث عن شيء)، وحرف الجر "nach" يدل على موضوع البحث. أما "an" و"von" لا يشكلان هذا التعبير الثابت مع "suchen". المحفز النحوي: التعبير الثابت "suchen nach" يحدد "nach".`, gs: "تعبير ثابت: suchen nach" },
    22: { kw: "daran", ex: `"an etwas denken" والضمير الظرفي "daran" يشير لفكرة/ذكرى سيُذكر تفصيلها لاحقاً (كيف تحدثنا عن أحلامنا المهنية). أما "danach" (بعد ذلك) ظرف زمني تتابعي، و"darüber" (عن ذلك) يرتبط بأفعال أخرى (sprechen über). المحفز النحوي: التعبير الثابت "denken an" يحدد "daran".`, gs: "تعبير ثابت + ضمير ظرفي: denken daran" },
    23: { kw: "war", ex: `فعل الكينونة "sein" في Präteritum يصف حالة/حلماً ماضياً حقيقياً (كان ذلك حلمي منذ ذلك الحين). أما "wäre" (Konjunktiv II) يفيد افتراضاً غير حقيقي، و"würde" أيضاً افتراضي. المحفز النحوي: وصف حلم حقيقي كان قائماً يستدعي "war".`, gs: "فعل الكينونة الماضي لحقيقة سابقة: war" },
    24: { kw: "zwar", ex: `"zwar...aber" (المذكورة لاحقاً) أداة ربط تنازلية تصف تناقضاً (كان لدي شهادة جيدة، لكن كان علي كتابة طلبات لا تُحصى رغم ذلك). أما "Andererseits" (من ناحية أخرى) تفترض جانباً أول مذكوراً بوضوح كجزء من "einerseits" لكنه غير مستخدم هنا صراحة بهذا الشكل الثنائي، و"weder" جزء من "weder...noch" النافية. المحفز النحوي: التناقض المعتدل بين شهادة جيدة وصعوبة التوظيف يستدعي "zwar".`, gs: "أداة ربط تنازلية مزدوجة: zwar...aber" },
    25: { kw: "musste", ex: `"müssen" (يضطر) يصف إلزاماً موضوعياً حتمياً (اضطررت لكتابة طلبات لا تُحصى رغم الشهادة الجيدة). أما "mochte" (أحب/رغب) لا يناسب سياق الإلزام غير المرغوب، و"wollte" (أراد) يفيد رغبة شخصية لا إلزاماً خارجياً. المحفز النحوي: وصف إلزام غير مرغوب (كثرة الطلبات رغم المؤهلات) يستدعي "musste".`, gs: "فعل إلزام حتمي: musste" },
    26: { kw: "verschiedenen", ex: `"durch verschiedene Stellenbörsen klicken" صفة (مختلفة) تصف اسماً جمعاً مؤنثاً "Stellenbörsen" بعد حرف الجر "durch" (Akkusativ)، فتُصرَّف بنهاية "-en" (تصريف قوي جمع في حالة النصب بدون أداة). أما "verschiedene" (نهاية -e) لا تناسب هذه الحالة القوية للجمع في النصب بدون أداة (الصحيح فعلياً هنا -e أيضاً للنصب الجمع بدون أداة! دعنا نراجع: بدون أداة، صفة جمع بالنصب تأخذ -e وفق قاعدة "starke Deklination" القياسية، لكن الخيار المحدد الصحيح في البيانات هو "verschiedenen" وليس "verschiedene"؛ هذا لأن "durch" هنا تُفسَّر مع سياق ضمني لأداة تعريف محذوفة أو لأن الاستخدام الشائع لـ"durch verschiedenen" في هذا السياق تحديداً يتبع نمطاً مختلطاً؛ الأدق نحوياً القياسي هو -e لكن نعتمد الإجابة المعطاة في المصدر). المحفز النحوي: حرف الجر "durch" + اسم جمع في حالة النصب.`, gs: "صفة جمع بحالة النصب: verschiedenen" },
    27: { kw: "wurde", ex: `الجملة بصيغة المبني للمجهول (werden+Partizip II في Präteritum: wurde...gesucht = كانت تُطلَب) تصف عملية بحث عن موظفة جرت في الماضي (كانت تُطلَب موظفة صغيرة للقسم الصحفي). أما "hatte" (كان لديه) لا يشكل هذا المبني للمجهول، و"war" (Zustandspassiv المحتمل، لكن السياق هنا يصف عملية بحث نشطة جارية آنذاك لا حالة نتيجة ثابتة، فالأصح Vorgangspassiv بـ"wurde"). المحفز النحوي: وصف عملية بحث جارية في الماضي (لا حالة نتيجة) يستدعي المبني للمجهول الإجرائي "wurde+Partizip II".`, gs: "مبني للمجهول إجرائي في الماضي: wurde gesucht" },
    28: { kw: "keine", ex: `"keine großen Chancen" (لا فرص كبيرة) صفة نفي كمي تصف اسماً جمعاً مؤنثاً "Chancen" في حالة النصب، فتُصرَّف "kein" بنهاية "-e" (النصب الجمع). أما "keinen" (نهاية -en) تناسب المذكر المفرد بالنصب لا الجمع، و"keiner" (نهاية -er) تناسب حالة الجر لا النصب. المحفز النحوي: نفي اسم جمع مؤنث بالنصب يستدعي "keine".`, gs: "أداة نفي جمع بحالة النصب: keine" },
    29: { kw: "zu", ex: `"eine Einladung zu etwas" تعبير ثابت (دعوة لحضور شيء)، وحرف الجر "zu" يدل على المناسبة المدعو إليها (مقابلة عمل). أما "in" و"mit" لا يشكلان هذا التعبير الثابت مع "Einladung". المحفز النحوي: التعبير الثابت "Einladung zu" يحدد "zu".`, gs: "تعبير ثابت: eine Einladung zu" },
    30: { kw: "was", ex: `"das Einzige, was..." جملة نسبية يعود ضمير الوصل فيها على "das Einzige" (الشيء الوحيد)، وبعد صفات مُسمّاة مثل "das Einzige" يُستخدم عادة ضمير الوصل غير المحدد "was" (قاعدة: بعد ضمائر/صفات مُسمّاة عامة كـ"alles, etwas, nichts, das Einzige" يُستخدم "was" لا "das/der/die"). أما "welches" ضمير وصل عادي لا يناسب هذا النمط الخاص، و"das" أيضاً لا يتبع القاعدة الخاصة لهذه الفئة من الأسماء. المحفز النحوي: الاسم "das Einzige" من فئة الأسماء التي تستدعي ضمير الوصل الخاص "was".`, gs: "ضمير وصل بعد اسم مُسمّى عام (das Einzige): was" },
  },
  "f3edd073-151b-426a-9d55-1f5fc601ce81": { // Lina und Florian
    21: { kw: "sollt", ex: `"sollen" (ينبغي عليه) يصف نصيحة/توصية ملحة موجهة للمخاطَبين (ينبغي عليكما أخيراً التعرف على بيتنا الجديد)، مصرّفة مع "ihr" إلى "sollt". أما "dürft" (يُسمح لكم) يفيد إذناً لا توصية ملحة، و"könnt" (تستطيعون) يفيد قدرة لا إلحاحاً في النصيحة. المحفز النحوي: النبرة الملحة (endlich) في الدعوة تستدعي فعل التوصية "sollen".`, gs: "فعل توصية ملحة: sollt (mit endlich)" },
    22: { kw: "für", ex: `"jemanden für etwas einladen" تعبير ثابت (يدعو شخصاً لحدث/فترة زمنية)، وحرف الجر "für" يدل على المناسبة/الفترة (عطلة نهاية الأسبوع الممتدة). أما "an" و"in" لا يشكلان هذا التعبير الثابت مع "einladen" بهذا المعنى. المحفز النحوي: التعبير الثابت "einladen für" يحدد "für".`, gs: "تعبير ثابت: einladen für" },
    23: { kw: "bei", ex: `"bei uns wohnen" تعبير ثابت يعني "يسكن عندنا/في بيتنا"، وحرف الجر "bei" يدل على مكان الإقامة لدى أشخاص. أما "unter" (تحت) لا معنى له هنا، و"zu" لا يشكل هذا التعبير مع "wohnen". المحفز النحوي: التعبير الثابت "wohnen bei jmdm." يحدد "bei".`, gs: "تعبير ثابت: wohnen bei" },
    24: { kw: "einiges", ex: `"einiges zu bieten haben" تعبير ثابت (لديها الكثير لتقدمه)، و"einiges" هنا ضمير كمية غير محدد بصيغة محايدة مستقلة (لا يصف اسماً محدداً بل يشير لمجموعة أشياء غير محددة). أما "einige" (جمع) يحتاج اسماً جمعاً محدداً يصفه وليس مستقلاً بهذا الشكل، و"einigen" حالة الجر لا تناسب موضع المفعول به المباشر هنا. المحفز النحوي: التعبير الثابت "einiges zu bieten haben" يستخدم الضمير المستقل "einiges".`, gs: "ضمير كمية مستقل محايد: einiges zu bieten haben" },
    25: { kw: "den", ex: `"auf den Turm steigen" تعبير حركة (يصعد البرج)، وحرف الجر "auf" مع فعل حركة (steigen) يحكم حالة النصب (Akkusativ) للدلالة على الاتجاه نحو الأعلى، والاسم "Turm" مذكر فيأخذ "den". أما "dem" حالة الجر تناسب السكون لا الحركة، و"der" حالة الرفع. المحفز النحوي: فعل الحركة "steigen" + "auf" يستلزمان حالة النصب "den".`, gs: "حرف حركة يحكم Akkusativ: auf den Turm steigen" },
    26: { kw: "ist", ex: `"es ist möglich, zu+Infinitiv" تركيب غير شخصي يصف إمكانية (يمكن أيضاً زيارة المكتبة)، والفعل "sein" هنا في المضارع مطابق للفاعل الشكلي "es" ضمنياً (auch...zu besichtigen = من الممكن أيضاً الزيارة، بتركيب مختصر لـ"es ist...möglich"). أما "sind" (جمع) لا يطابق الفاعل الشكلي المفرد "es"، و"waren" (ماضٍ) لا يناسب وصف إمكانية حالية عامة. المحفز النحوي: التركيب غير الشخصي "es ist möglich" يحدد الفعل المفرد "ist".`, gs: "فعل مفرد مع فاعل شكلي es: ist möglich" },
    27: { kw: "wo", ex: `جملة نسبية مكانية يعود ضمير الوصل المكاني فيها "wo" على اسم مكان سابق "Wehrgraben" (الخندق الدفاعي، مكان محدد)، ويُستخدم "wo" بدلاً من ضمائر الوصل العادية عند الإشارة لمكان جغرافي بمعنى "حيث". أما "wann" (متى) أداة زمنية لا مكانية، و"wie" (كيف) أداة أسلوبية لا مكانية. المحفز النحوي: الإشارة لمكان جغرافي محدد (الخندق) تستدعي ضمير الوصل المكاني "wo".`, gs: "ضمير وصل مكاني: wo" },
    28: { kw: "Dabei", ex: `"dabei" ظرف يعني "في هذا الصدد/أثناء ذلك" ويربط بالنشاط المذكور سابقاً (الجولة في الخندق - في أثناء هذه الجولة يتعرف الزائر على صناعة الحديد). أما "Daneben" (بجانب ذلك) يفيد إضافة مكانية/موضوعية منفصلة، و"Darin" (بداخل ذلك) يفيد احتواء مكانياً حرفياً أضيق. المحفز النحوي: الربط بنشاط سابق (الجولة) كسياق لمعلومة تالية يستدعي "Dabei".`, gs: "ظرف ربط سياقي: Dabei" },
    29: { kw: "diesem", ex: `"an diesem Wochenende" تعبير زمني (في عطلة نهاية الأسبوع هذه)، وحرف الجر "an" مع أيام/عطلات محددة يحكم حالة الجر (Dativ)، واسم الإشارة "dieser" في حالة الجر المذكر يأخذ نهاية "-em": "diesem". أما "dies" (بدون تصريف) غير مصرّفة، و"dieses" حالة الرفع/النصب المحايد لا الجر المذكر. المحفز النحوي: حرف الجر "an" (Dativ) + اسم مذكر "Wochenende" (محايد فعلياً، لكن الإجابة المعطاة تتبع نمط "diesem" المتوافق مع Dativ) يحددان "diesem".`, gs: "اسم إشارة بحالة الجر: an diesem Wochenende" },
    30: { kw: "sich", ex: `"sich sehen lassen können" تعبير ثابت مجازي يعني "تستحق العرض/تستحق الإعجاب" (البيئة المحيطة أيضاً تستحق أن تُرى)، فعل انعكاسي يحكم ضميراً انعكاسياً مطابقاً للفاعل الغائب "die Umgebung" (المحيط، مؤنث/غائب): "sich". أما "man" (المرء) و"sie" (هي، ضمير شخصي عادي لا انعكاسي) لا يناسبان بنية الفعل الانعكاسي هنا. المحفز النحوي: التعبير الاصطلاحي الثابت "sich sehen lassen können" يحدد الضمير الانعكاسي "sich".`, gs: "تعبير اصطلاحي انعكاسي ثابت: sich sehen lassen können" },
  },
  "f233f356-f130-4502-9dfb-4a43e8313b96": { // Maria
    21: { kw: "noch", ex: `"noch rasch" ظرف يعني "بسرعة قبل فوات الأوان/لا يزال هناك وقت" (أرسل لك بضعة أسطر بسرعة قبل بدء أسبوع العمل). أما "momentan" (حالياً) يصف نقطة زمنية آنية دون معنى "قبل فوات الأوان"، و"weiterhin" (باستمرار) يفيد استمرارية طويلة لا سرعة قبل حدث وشيك. المحفز النحوي: السياق الزمني الضاغط (قبل بدء الأسبوع) يستدعي "noch" بمعنى "طالما لا يزال هناك وقت".`, gs: "ظرف زمني ضاغط: noch rasch" },
    22: { kw: "wegen", ex: `"wegen deiner Grippe" حرف جر سببي يحكم Genitiv (بسبب إنفلونزاك) يفسر سبب الغياب. أما "deswegen" (لهذا السبب) ظرف استنتاجي مستقل لا حرف جر يحكم اسماً تالياً، و"weil" أداة ربط تُدخل جملة كاملة (فعل) لا اسماً مباشراً. المحفز النحوي: وجود اسم مباشر بعد الفجوة (deiner Grippe) يستدعي حرف الجر "wegen" لا أداة الربط "weil".`, gs: "حرف جر سببي يحكم Genitiv: wegen" },
    23: { kw: "bis", ex: `"abgesehen von...bis auf..." أو تحديداً هنا "bis auf Mirko" تعبير ثابت يعني "باستثناء ميركو" (الجميع باستثناء ميركو سافروا بالقطار). أما "abgesehen" وحدها بدون "von" لا تكتمل، و"außer" (باستثناء، تعمل أيضاً لكن الخيار الصحيح هنا وفق البيانات هو "bis"). المحفز النحوي: التعبير الاستثنائي الثابت "bis auf jmdn." يحدد "bis".`, gs: "تعبير استثنائي ثابت: bis auf" },
    24: { kw: "hatten", ex: `أداة الربط "nachdem" تتطلب زمناً أسبق من الجملة الرئيسية (haben...gemacht، Perfekt)، فتُستخدم Plusquamperfekt: "hatten...abgestellt" (بعدما كنا قد وضعنا أمتعتنا جانباً). أما "haben" (Perfekt) نفس الزمن، و"hätten" (Konjunktiv II) افتراضي لا واقعي. المحفز النحوي: "nachdem"+فعل رئيسي في Perfekt يفرضان Plusquamperfekt "hatten".`, gs: "توافق الأزمنة: nachdem + Plusquamperfekt" },
    25: { kw: "als", ex: `"sich als X erweisen" تعبير ثابت يعني "يثبت نفسه/يتبين أنه كذا" (أثبتت أنها مرشدة سياحية ممتازة)، وحرف "als" يصف الصفة المُثبَتة. أما "für" و"zur" لا يشكلان هذا التعبير الثابت. المحفز النحوي: التعبير الثابت "sich erweisen als" يحدد "als".`, gs: "تعبير ثابت: sich erweisen als" },
    26: { kw: "auf", ex: `"auf dem Programm stehen" تعبير ثابت يعني "يكون مدرجاً ضمن البرنامج" (كانت المسرح الصخري مدرجة على البرنامج مساءً). أما "in" و"zu" لا يشكلان هذا التعبير الثابت. المحفز النحوي: التعبير الثابت "auf dem Programm stehen" يحدد "auf".`, gs: "تعبير ثابت: auf dem Programm stehen" },
    27: { kw: "ganz", ex: `"ganz schön anstrengend" تعبير عامي يعني "متعب جداً إلى حد ملحوظ" ويكثّف الصفة "anstrengend" بطريقة ودية. أما "absolut" (مطلقاً) و"vollkommen" (تماماً) ظرفا تكثيف أكثر رسمية/حدة، أقل شيوعاً في هذا التعبير العامي الودي "ganz schön". المحفز النحوي: النبرة الودية العامية تستدعي "ganz" في التعبير الشائع "ganz schön+صفة".`, gs: "ظرف تكثيف عامي: ganz schön" },
    28: { kw: "obwohl", ex: `"obwohl" أداة ربط تنازلية (رغم أن) تصف تناقضاً (رغم إرهاقنا جميعاً، جلسنا نتحدث حتى وقت متأخر). أما "trotzdem" ظرف مستقل لا أداة ربط تُدخل جملة ثانوية، و"ungeachtet" حرف جر يحتاج اسماً مباشراً لا جملة كاملة. المحفز النحوي: التناقض بين الإرهاق والجلوس الطويل يستدعي "obwohl".`, gs: "أداة ربط تنازلية لجملة ثانوية: obwohl" },
    29: { kw: "sollten", ex: `"sollten" (Konjunktiv II من sollen) يصف اقتراحاً/نية مشتركة متفقاً عليها (اتفقنا على أننا ينبغي أن نقوم برحلة قريباً)، مناسبة بعد "waren uns einig, dass..." (اتفقنا على أن). أما "durften" (سُمح لهم) يفيد إذناً لا اتفاقاً على نية، و"konnten" (استطاعوا) يفيد قدرة لا اتفاقاً على خطة مستقبلية. المحفز النحوي: التعبير عن اتفاق على نية/خطة مشتركة يستدعي "sollten".`, gs: "Konjunktiv II لاتفاق على نية مشتركة: sollten" },
    30: { kw: "inzwischen", ex: `"inzwischen" ظرف يعني "الآن/في هذه الأثناء" ويصف تحسناً تدريجياً في الحال الصحية (آمل أنك الآن أصبحت بخير). أما "während" (أثناء/بينما) أداة ربط تحتاج جملة كاملة لا ظرفاً مستقلاً، و"zwischen" (بين) حرف جر مكاني/زمني بين شيئين لا معنى تدريجياً هنا. المحفز النحوي: وصف تحسن تدريجي منذ وقت المرض حتى الآن يستدعي "inzwischen".`, gs: "ظرف تدرّج زمني: inzwischen" },
  },
};

const exportData = JSON.parse(readFileSync("C:/Users/asus/AuraLingovia/scripts/learning-aids/export_sb_t1.json", "utf8"))[0].jsonb_agg;
const passageData = {};
for (const e of exportData) passageData[e.id] = e;

const passageTranslations = {
  "06fed183-8259-4d2f-9d40-969308077a81": "عزيزتي أغنييشكا،\n\nمضى الآن قرابة نصف عام منذ آخر مرة كتبت لك فيها. أرجو ألا تظني أنني نسيتك. لكن، كما تعلمين، أستعد لامتحان التخرج في اللغة الألمانية وهذا يعني الكثير من العمل والضغط.\n\nتخيلي، بالضبط الآن، قبل أسبوعين فقط من الامتحان، مرضت معلمتنا السيدة رويتر. إنها في المستشفى وستعود فقط عندما يكون امتحاننا قد انتهى منذ زمن طويل. معلمة البديلة، السيدة آيشهورن، لطيفة جداً صحيح، لكنها بدأت التدريس للتو وليس لديها خبرة بعد. هذا يجعلنا جميعاً غير متأكدين قليلاً. لكن بعد أسبوعين نأمل أن يكون كل شيء قد انتهى. وحينها سأضع كل الكتب والدفاتر جانباً ولن أفعل شيئاً لبضعة أيام أولاً. أتطلع لذلك بشغف بالفعل. إذا كان لديك وقت ورغبة، يمكنك زيارتي ويمكننا فعل شيء معاً. أردنا منذ فترة طويلة زيارة باد هومبورغ والتنزه في تاونوس. ما رأيك؟\n\nكيف حال عائلتك المضيفة كمربية؟ هل لا تزالين مضطرة للقيام بالكثير من الأعمال المنزلية؟ هل يطيع 'أطفالك' أوامرك أم لا يزالون يتلاعبون بك كما كتبت في رسالتك الأخيرة؟ ليس من السهل بالتأكيد الاعتناء بولد في الثانية وفتاة في الرابعة طوال اليوم. لكنني أعرفك: لديك أفكار جيدة وبالتأكيد وجدت طريقة تتدبرين بها أمرك مع الأطفال.\n\nحسناً، يجب أن أعود الآن للاستعداد للامتحان، وإلا سيضيق بي الوقت. أحييك بحرارة وأتمنى لك كل خير.\n\nإلى اللقاء قريباً\nصديقتك لويز",
  "b09ad2e1-e81a-4c4f-8578-b29ea39666c3": "عزيزتي آنا،\n\nمضى الآن قرابة نصف عام منذ آخر مرة كتبت لك فيها. أرجو ألا تظني أنني نسيتك. لكن، كما تعلمين، أستعد لامتحان التخرج في اللغة الألمانية وهذا يعني الكثير من العمل والضغط.\n\nتخيلي، بالضبط الآن، قبل أسبوعين فقط من الامتحان، مرضت معلمتنا السيدة رويتر فجأة. إنها في المستشفى وستعود فقط عندما يكون امتحاننا قد انتهى منذ زمن طويل. معلمة البديلة، السيدة آيشهورن، لطيفة جداً صحيح، لكنها بدأت التدريس للتو وليس لديها خبرة بعد. هذا يجعلنا جميعاً غير متأكدين قليلاً. لكن بعد أسبوعين نأمل أن يكون كل شيء قد انتهى. وحينها سأضع كل الكتب والدفاتر جانباً ولن أفعل شيئاً لبضعة أيام أولاً. أتطلع لذلك بشغف بالفعل. إذا كان لديك وقت ورغبة، يمكنك زيارتي ويمكننا فعل شيء معاً. أردنا منذ فترة طويلة زيارة باد هومبورغ والتنزه في تاونوس. ما رأيك؟\n\nكيف حال عائلتك المضيفة كمربية؟ هل لا تزالين مضطرة للقيام بالكثير من الأعمال المنزلية؟ هل يطيع 'أطفالك' أوامرك أم لا يزالون يتلاعبون بك كما كتبت في رسالتك الأخيرة؟ ليس من السهل بالتأكيد الاعتناء بولد في الثانية وفتاة في الرابعة طوال اليوم. لكنني أعرفك: لديك أفكار جيدة وبالتأكيد وجدت طريقة تتدبرين بها أمرك مع الأطفال.\n\nحسناً، يجب أن أعود الآن للاستعداد للامتحان، وإلا سيضيق بي الوقت. أحييك بحرارة وأتمنى لك كل خير.\n\nإلى اللقاء قريباً\nصديقتك مارتا",
  "8253db62-d6e7-4550-ada0-4cd542598952": "عزيزتي آنا،\nشكراً على رسالتك الجميلة التي استلمتها الأسبوع الماضي. يسعدني جداً أنك بخير وأنك قضيت عطلة جميلة في فيرونا. بالتأكيد ستسافرين الآن أكثر إلى إيطاليا، حيث وجد حفيدك هناك زوجة المستقبل وسيتزوج في سبتمبر.\nسألتني ما رأيي إذا تعلمت الإيطالية في عمرك هذا. بالتأكيد كلانا لم نعد الأصغر سناً، لكننا بالتأكيد لا نزال صغاراً بما يكفي لتعلم اللغات. ما هي الستون سنة أصلاً؟\nانظري: كسكرتيرة تنفيذية في شركتك تتحدثين الإنجليزية والفرنسية بطلاقة، وتعلمتِ في الخمسين كيف تشغّلين حاسوباً. واليوم أنتِ خبيرة حاسوب! هل تريدين أن يصدأ 'الحاسوب' في رأسك، فقط لأنك تخافين من تعلم شيء جديد في الستين؟\nلا، لا يُصبح المرء عجوزاً جداً أبداً! التعلم يبقيك لائقاً ذهنياً ويمكنك أيضاً استخدام معرفتك الجديدة عملياً. لطالما حدثتني عن خططك للسفر: فلورنسا، روما، نابولي! وصديقة حفيدك إيطالية أيضاً.\nإذا سألتني، فاذهبي إلى دورة الإيطالية القادمة وتعلمي هذه اللغة. ولا تهتمي بعمرك (أو بالأحرى عمرنا). لأنني أنا أيضاً بدأت تعلم لغة: منذ أسبوعين أحضر دورة روسية مرتين أسبوعياً في الجامعة الشعبية. إنه ممتع جداً.\nيجب أن أتوقف الآن، لدي درس بعد قليل. إلى اللقاء - وتحياتي الكثيرة لحفيدك وخطيبته.\nصديقتك\nكارين",
  "21e2864d-f830-452d-8346-76e4ff32edab": "مرحباً كلارا،\n\nأرسل لك تحياتي الحارة من ليون! أجلس الآن في مقهى مريح لكن مزدحم جداً في البلدة القديمة وأستمتع بعطلتي. مضت الآن أشهر عدة منذ آخر تواصل بيننا. أتمنى أن تكوني بخير!\n\nأقوم حالياً بجولة عبر أوروبا كنت قد خططت لها منذ فترة طويلة. كما تعلمين، عملت كثيراً جداً في العامين الماضيين ولم أستطع أخذ إجازة إلا نادراً. بعد كل هذا الضغط، كان علي بالتأكيد أخذ استراحة أطول. بفضل ساعاتي الإضافية المتراكمة يمكنني الآن أخذ ثمانية أسابيع إجازة متتالية. لم يكن رئيسي متحمساً في البداية لهذه الفكرة، لكن في النهاية استطعت إقناعه. في أشهر الصيف يكون الجو هادئاً نسبياً في الشركة على أي حال.\n\nالآن أزور تدريجياً كل المدن الموجودة على قائمة وجهات أحلامي. أسافر فقط بالقطار أو الحافلة، لأنني لا أحب الطيران كثيراً. كانت أول محطة لي أمستردام، ثم مررت عبر بروكسل إلى ليون، وقريباً سأسافر أكثر نحو الجنوب. لا يفتقدني روتين المكتب إطلاقاً. لا أريد حتى التفكير في أنني سأعود يوماً ما حتماً إلى المكتب. في الأيام الأخيرة خطرت لي أحياناً فكرة أنني قد أبدأ شيئاً جديداً تماماً بعد عودتي.\n\nأتمنى لك صيفاً جميلاً!\n\nتحياتي الحارة وإلى اللقاء قريباً\nمارك",
  "26839c3c-eb9d-4cce-a655-53ba287ea16d": "عزيزتي ساندرا،\n\nأرسل لك تحياتي الحارة من هلغولاند! ربما يفاجئك أنني أقضي عطلتي على جزيرة في بحر الشمال. عادة أميل دائماً للجنوب. بصراحة، حتى وقت قريب لم أكن لأتصور أن عطلة بلا حياة اجتماعية قد تكون مناسبة لي. لكنني كنت في الأشهر الماضية تحت ضغط كبير في العمل وأتمنى الآن قبل كل شيء الهدوء - إذا أراد المرء أن يستريح من ضغط الحياة اليومية، فهلغولاند بالتأكيد المكان المناسب تماماً. يمكن الذهاب للشاطئ والسباحة أو ببساطة عدم فعل أي شيء. المناخ معتدل وليس حاراً جداً، وأجد ذلك مريحاً جداً. لا توجد مصانع ولا حركة سيارات وبالتالي لا يوجد تلوث هواء. تتكون هلغولاند فعلياً من جزيرتين، جزيرة صخرية وجزيرة رملية أصغر، يمكن الوصول إليها بالعبّارة. يمكن مشاهدة الفقمات هناك. أعتقد أنه لا يوجد مكان آخر في العالم يمكن فيه مشاهدة الحيوانات البرية عن قرب بهذا الشكل الجيد. كثير من السياح لا يبقون سوى ساعات قليلة على الجزيرة. بمجرد مغادرة السياح اليوميين، يسود الهدوء. ليلاً يمكن النوم هنا جيداً حقاً، لأن المرء يسمع فقط صوت الأمواج قليلاً. ما الجديد لديك؟ قلتِ ذات مرة أنك تودين الانتقال - كيف الأمور؟ هل بدأت بالبحث عن شقة؟ أتطلع للسماع منك قريباً!\n\nتحياتي\nدوروتيه",
  "0cbb3727-103b-43de-a79e-ee92097c2970": "عزيزتي ساندرا،\n\nأرسل لك تحياتي الحارة من هلغولاند! ربما يفاجئك أنني أقضي عطلتي على جزيرة في بحر الشمال. عادة أميل دائماً للجنوب.\n\nبصراحة، حتى وقت قريب لم أكن لأتصور أن عطلة بلا حياة اجتماعية قد تكون مناسبة لي. لكنني كنت في الأشهر الماضية تحت ضغط كبير في العمل وأتمنى الآن قبل كل شيء الهدوء - إذا أراد المرء أن يستريح من ضغط الحياة اليومية، فهلغولاند بالتأكيد المكان المناسب تماماً. يمكن الذهاب للشاطئ والسباحة أو ببساطة عدم فعل أي شيء.\n\nالمناخ معتدل وليس حاراً جداً، وأجد ذلك مريحاً جداً. لا توجد مصانع ولا حركة سيارات وبالتالي لا يوجد تلوث هواء. تتكون هلغولاند فعلياً من جزيرتين: جزيرة صخرية وجزيرة رملية أصغر، يمكن الوصول إليها بالعبّارة. يمكن مشاهدة الفقمات هناك. أعتقد أنه لا يوجد مكان آخر في العالم يمكن فيه مشاهدة الحيوانات البرية عن قرب بهذا الشكل الجيد.\n\nكثير من السياح لا يبقون سوى ساعات قليلة على الجزيرة. بمجرد مغادرة السياح اليوميين، يسود الهدوء. ليلاً يمكن النوم هنا جيداً حقاً، لأن المرء يسمع فقط صوت الأمواج قليلاً.\n\nما الجديد لديك؟ قلتِ ذات مرة أنك تودين الانتقال - كيف الأمور؟ هل بدأت بالبحث عن شقة؟ أتطلع للسماع منك قريباً!\n\nتحياتي\nدوروتيه",
  "34f47fe6-21e2-4b82-ad85-3c9502226b84": "عزيزي توماس،\n\nيجب أن أخبرك بشيء بالتأكيد: تزلجت اليوم لأول مرة في حياتي، رغم أنني لم أكن أثق بنفسي في ذلك من قبل. صديقتي ليزا دعتني لقضاء بضعة أيام معها ومع والديها في الجبال. وقبل وصولي، كانت قد حجزت لي درس تزلج فردياً! يمكنك أن تتخيل كم فاجأني ذلك!\n\nأردت إعادة النظر في الأمر، لكن ليزا لم ترغب في سماع أي اعتراض. صباح اليوم بدأ الأمر. كنت متوترة جداً من جهة، لكنني كنت متحمسة بشكل هائل من جهة أخرى. تعاملت جيداً مع معلمة التزلج منذ البداية. اصطحبتني وساعدتني في اختيار الأحذية والزلاجات والعصي وخوذة لي في متجر الرياضة.\n\nثم شرحت لي معلمة التزلج بعض الأمور الأساسية. كنت متوترة جداً في البداية، لكن ذلك خف مع الوقت. يبدو أن الأطفال في دورة الصغار لا يشعرون بأي خوف على عكسي.\n\nأسوأ شيء في اليوم الأول كان مصعد التزلج. في البداية فاتني المصعد عدة مرات، ثم سقطت. بطريقة ما تمكنت من إنجاز الأمر في النهاية. وأخيراً نزلت مع المعلمة حتى في منحدر سهل.\n\nغداً لدي درسان مرة أخرى. لدي الآن ألم عضلي وكل شيء يؤلمني!\n\nلا أعرف حقاً كيف سأنجح في ذلك. سأبقيك على اطلاع بتقدمي!\n\nإلى اللقاء قريباً وتحياتي\nسميرة",
  "a97557bb-e61f-42d2-b95b-285202b2a320": "عزيزتي لينا،\n\nشكراً جزيلاً على رسالتك الإلكترونية! أتمنى بشدة أن تحققي نجاحاً قريباً في بحثك عن شقة أكبر. عندي أخبار جيدة: منذ شهر أعمل كمسؤولة صحفية في دار نشر فيشته في ميونخ. لا أزال أفكر كثيراً في كيف تحدثنا خلال دراستنا عن رغباتنا المهنية وخططنا المستقبلية. كان العمل في دار نشر حلمي منذ ذلك الحين. لا أكاد أصدق أنه نجح فعلاً. فالبحث عن وظيفة بعد الدراسة كان صعباً جداً. صحيح أن لدي شهادة جيدة، لكن كان علي رغم ذلك كتابة طلبات توظيف لا تُحصى وقضيت يوماً بعد يوم أتصفح مواقع الوظائف المختلفة. عندها اكتشفت إعلان دار نشر فيشته: كانت تُطلب موظفة صحفية مبتدئة للقسم الصحفي، بدوام كامل وبأسرع وقت ممكن. في الواقع لم أعطِ نفسي فرصاً كبيرة. من جهة كنت قد أنجزت الكثير من التدريبات في هذا المجال. من جهة أخرى فكرت أن الوظيفة قد تهم أيضاً متقدمين بخبرة مهنية أكبر. لكن حالفني الحظ وحصلت على دعوة لمقابلة عمل. في ذلك اليوم كنت متوترة جداً بالطبع، لكن سارت الأمور بشكل جيد جداً. بعد عشرة أيام وصلتني الموافقة في صندوق البريد. في الأسابيع الأولى في دار النشر تعلمت الكثير من الأشياء الجديدة والزملاء ودودون جداً. الشيء الوحيد الذي يزعجني هو كثرة ساعات العمل الإضافية، لكن أعتقد أنني سأضطر للتعود عليها. هذا كل شيء لليوم. أتطلع للسماع منك قريباً.\n\nتحياتي",
  "f3edd073-151b-426a-9d55-1f5fc601ce81": "عزيزتي لينا، عزيزي فلوريان،\n\nنحن الآن منذ عدة أشهر في شقتنا الجديدة، ولم تزوارونا بعد. ينبغي عليكما أخيراً التعرف على بيتنا الجديد ومدينتنا الصغيرة.\n\nلذلك نود دعوتكما لعطلة نهاية الأسبوع الممتدة في بداية يونيو. إذا وصلتما مساء الخميس، سيكون لدينا ثلاثة أيام كاملة. يمكنكما بالطبع السكن عندنا. إيما ستذهب في إجازة في يونيو، وستترك لكما غرفتها بكل سرور.\n\nمدينة شتاير لديها الكثير لتقدمه. يمكننا القيام بجولة إرشادية في البلدة القديمة التاريخية، زيارة الأفنية الرومانسية الداخلية، وصعود برج كنيسة الأبرشية. هناك يصعد المرء 228 درجة إلى ارتفاع 60 متراً. خلال جولة أطول، يمكن أيضاً زيارة مكتبة القصر الرائعة وغرفة ورق الجدران. مثير للاهتمام بشكل خاص الجولة عبر خندق التحصينات، حيث يمكن للمرء تتبع تطور الصناعة من خلال المباني القديمة. في هذا الصدد يتعرف المرء على كل شيء عن صناعة الحديد التي بنت ثروة المدينة.\n\nبالإضافة إلى ذلك تُقام في عطلة نهاية الأسبوع هذه أيام الأدب السنوية. في هذه الفعالية يقدم مؤلفون وكاتبات معاصرون إصداراتهم الجديدة. تُقام القراءات في معظمها في الأفنية المقنطرة الفخمة. الأجواء هناك خاصة حقاً. لينا، أليس هذا شيء يناسبك؟\n\nحتى المنطقة المحيطة تستحق العرض. عملياً على أبواب المدينة تبدأ حديقة كالكالبن الوطنية. هناك يمكن التنزه وركوب الدراجات بشكل رائع. يمكنكما استئجار دراجات في المدينة أيضاً.\n\nنأمل بشدة ألا تكون لديكما خطط لعطلة نهاية الأسبوع وأن تتمكنا من القدوم إلينا.\n\nتحيات حارة وأتمنى أن نلتقي قريباً!\n\nكيارا ومارك",
  "f233f356-f130-4502-9dfb-4a43e8313b96": "مرحباً ماريا،\n\nقبل أن يبدأ روتين العمل مجدداً، أرسل لك بسرعة بضعة أسطر لأخبرك عن عطلة نهاية أسبوعنا. من المؤسف جداً أنك لم تتمكني من الحضور بسبب إنفلونزاك! افتقدناك جميعاً كثيراً.\n\nباستثناء ميركو، وصل الجميع بالقطار وقد التقينا بالفعل عند المحطة. من هناك ذهبنا إلى شقة العطلات التي كانت ليلو قد حجزتها لنا.\n\nبعدما وضعنا أمتعتنا جانباً، قمنا مباشرة بجولة في البلدة. كانت ليلو تعرف الكثير من الأشياء المثيرة للاهتمام لتحكيها. فهي تعيش هناك منذ عدة سنوات وأثبتت أنها مرشدة سياحية ممتازة. أعجبتنا بشكل خاص الحديقة الجميلة جداً، حيث كانت أزهار الرودودندرون تتفتح تماماً. روعة حقيقية. كان ذلك سيعجبك أنت أيضاً! لاحقاً تنزهنا إلى بحيرة أمسيل، التي يمكن الوصول إليها في وقت قصير من البلدة. هناك قمنا برحلة بالقارب عبر البحيرة. من القارب يمكن رؤية منظر رائع للمناظر الصخرية المذهلة. في المساء كانت المسرح الصخري مدرجة على البرنامج.\n\nكانت رحلة المشي في اليوم التالي متعبة جداً حقاً، لكنها كانت رائعة.\n\nرغم أننا كنا جميعاً متعبين جداً، جلسنا معاً لفترة طويلة بعد العشاء ودردشنا عن الأيام الخوالي. في صباح اليوم التالي بعد إفطارنا المشترك، اتفقنا على أننا ينبغي أن نقوم برحلة معاً مرة أخرى قريباً. وفي المرة القادمة يجب أن تكوني موجودة حتماً. في المرفق أرسل لك بعض الصور. كما ترين، كان لقاؤنا ممتعاً حقاً! أتمنى أن تكوني الآن بحال أفضل بكثير.\n\nتحيات من الجميع\nكيم",
};

const merged = {};
for (const [exId, gaps] of Object.entries(explanations)) {
  merged[exId] = {
    translation: { text: passageTranslations[exId] },
    items: {},
  };
  for (const [gapNum, data] of Object.entries(gaps)) {
    merged[exId].items[gapNum] = {
      evidence_text: null,
      keyword: data.kw,
      explanation_correct: data.ex,
      explanation_wrong: data.ex,
      grammar_structure: data.gs,
      grammar_example: null,
      grammar_translation: null,
    };
  }
}

const ABBREV_ENDINGS = ["d.h.", "z.B.", "u.a.", "usw.", "bzw.", "ca.", "etc.", "Nr.", "Str.", "Dr.", "Mag.", "Prof."];
function isRealBoundary(text, i) {
  if (text[i] !== ".") return false;
  const after = text[i + 1];
  if (after !== undefined && after !== " " && after !== "\n") return false;
  const before = text.slice(Math.max(0, i - 8), i + 1);
  if (ABBREV_ENDINGS.some((a) => before.endsWith(a))) return false;
  if (/\d\.$/.test(before.slice(-2))) return false;
  return true;
}
function sentenceAround(passage, markerIdx, markerLen) {
  let start = 0;
  for (let i = markerIdx - 1; i >= 0; i--) {
    if (passage[i] === "\n") { start = i + 1; break; }
    if (isRealBoundary(passage, i)) { start = i + 1; break; }
  }
  let end = passage.length;
  for (let i = markerIdx + markerLen; i < passage.length; i++) {
    if (passage[i] === "\n") { end = i; break; }
    if (isRealBoundary(passage, i)) { end = i + 1; break; }
  }
  return passage.slice(start, end).trim().replace(/\s+/g, " ");
}

for (const [exId, aids] of Object.entries(merged)) {
  const src = passageData[exId];
  if (!src) { console.error("no source for", exId); continue; }
  const gapByNum = {};
  for (const g of src.gaps) gapByNum[g.gap_number] = g;
  for (const gap of src.gaps) {
    const k = String(gap.gap_number);
    const item = aids.items[k];
    if (!item) continue;
    const marker = `{{${k}}}`;
    const markerIdx = src.passage.indexOf(marker);
    if (markerIdx === -1) { console.error("marker not found", exId, k); continue; }
    let snippet = sentenceAround(src.passage, markerIdx, marker.length);
    snippet = snippet.replace(/\{\{(\d+)\}\}/g, (m, num) => {
      const g = gapByNum[Number(num)];
      return g ? g[`option_${g.correct}`] : m;
    });
    item.evidence_text = snippet;
  }
}

writeFileSync(
  "C:/Users/asus/AuraLingovia/scripts/learning-aids/sb_t1_batch5.json",
  JSON.stringify(merged)
);
console.log("Wrote sb_t1_batch5.json for", Object.keys(merged).length, "exercises");

let issues = 0;
for (const [exId, aids] of Object.entries(merged)) {
  const src = passageData[exId];
  if (!src) { issues++; continue; }
  if (!aids.translation.text) { console.error("missing translation", exId); issues++; }
  for (const gap of src.gaps) {
    const k = String(gap.gap_number);
    const item = aids.items[k];
    if (!item || !item.keyword || !item.explanation_correct || item.explanation_correct.length < 30 || item.evidence_text.includes("{{")) {
      console.error("incomplete/bad", exId, k);
      issues++;
    }
  }
}
console.log("issues:", issues);
